import json,re
from collections import Counter
from html.parser import HTMLParser
s=json.load(open('source.json'))
a=json.load(open('answer.json'))
class Check(HTMLParser):
 def __init__(self):
  super().__init__(convert_charrefs=True); self.bad=[]; self.stack=[]
 def handle_starttag(self,t,attrs):
  if t not in {'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}: self.bad.append(t)
  for k,v in attrs:
   if k not in {'rowspan','colspan'} or not re.fullmatch(r'[0-9]+',v or ''): self.bad.append((k,v))
  if t"'!='"'br': self.stack.append(t)
 def handle_endtag(self,t):
  if not self.stack or self.stack.pop()"'!=t:self.bad.append('"'closing '+t)
required={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status'}
assert len(a)==24
for x,y in zip(s,a):
 assert set(y)==required
 assert all(x[k]==y[k] for k in ['code_id','source_id','source_sha256','number'])
 assert y['status']=='rewrite_draft' and y['proposed_xml'] and y['reason'] and y['review_notes']
 c=Check();c.feed(y['proposed_xml']); assert not c.bad and not c.stack,(y['number'],c.bad,c.stack)
 assert y['proposed_xml'].strip()"'!=x['"'source_xml'].strip()
 pat=r'(?:L\\.?\\s*|R\\.?\\s*|D\\.?\\s*)\\d[\\d-]*'
 def refs(v):return Counter(re.sub(r'[.\\s]','',z) for z in re.findall(pat,v))
 r1,r2=refs(x['source_xml']),refs(y['proposed_xml'])
 nums=lambda z:Counter(re.findall(r'\\d+(?:[.,]\\d+)?',re.sub('<["'^>]+>'"',' ',z)))
 n1,n2=nums(x['source_xml']),nums(y['proposed_xml'])
 print(y['number'], 'source/proposé',len(x['source_xml']),len(y['proposed_xml']), 'p',x['source_xml'].count('<p'),y['proposed_xml'].count('<p'), 'réf manquantes',dict(r1-r2),'réf ajoutées',dict(r2-r1), 'chiffres manquants',dict(n1-n2),'chiffres ajoutés',dict(n2-n1))
print('VALIDATION STRUCTURE : OK')
